module ct_vfdsu_srt_radix16_bound_table(
  bound_sel,
  digit_bound_1,
  digit_bound_2,
  digit_bound_3,
  digit_bound_4,
  digit_bound_5,
  digit_bound_6,
  digit_bound_7,
  digit_bound_8,
