  sqrt_first_round,
  sqrt_secd_round,
  sqrt_secd_round_sign
);

// &Ports; @23
input   [6 :0]  bound_sel;           
input           sqrt_first_round;    
input           sqrt_secd_round;     
input           sqrt_secd_round_sign; 
output  [11:0]  digit_bound_1;       
