// Author: Matteo Perotti <mperotti@iis.ee.ethz.ch>
// Description:
// Power-of-two stride generator and sequencer
// Load a new stride with stride_valid_i
// Generate the next power-of-two stride with update_i
// valid_o asserted if stride_p2_o is non-zero

module p2_stride_gen import ara_pkg::*; import rvv_pkg::*; import cf_math_pkg::idx_width; #(
  parameter integer unsigned NrLanes = 0
) (
  input  logic                                     clk_i,
  input  logic                                     rst_ni,
  input  logic          [idx_width(8*NrLanes)-1:0] stride_i,
  input  logic                                     valid_i,
  input  logic                                     update_i,
  output logic [idx_width(idx_width(8*NrLanes)):0] popc_o,
  output logic          [idx_width(8*NrLanes)-1:0] stride_p2_o,
  output logic                                     valid_o
);

  // Copyright 2018, 2021 ETH Zurich and University of Bologna.
//
// Copyright and related rights are licensed under the Solderpad Hardware
// License, Version 0.51 (the "License"); you may not use this file except in
// compliance with the License. You may obtain a copy of the License at
// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law
// or agreed to in writing, software, hardware and materials distributed under
// this License is distributed on an "AS IS" BASIS, WITHOUT WARRANTIES OR
// CONDITIONS OF ANY KIND, either express or implied. See the License for the
// specific language governing permissions and limitations under the License.
// SPDX-License-Identifier: SHL-0.51
//
// Author: Stefan Mach <smach@iis.ee.ethz.ch>
// Description: Common register defines for RTL designs



// Abridged Summary of available FF macros:
// `FF:      asynchronous active-low reset
// `FFAR:    asynchronous active-high reset
// `FFARN:   [deprecated] asynchronous active-low reset
// `FFSR:    synchronous active-high reset
// `FFSRN:   synchronous active-low reset
// `FFNR:    without reset
// `FFL:     load-enable and asynchronous active-low reset
// `FFLAR:   load-enable and asynchronous active-high reset
// `FFLARN:  [deprecated] load-enable and asynchronous active-low reset
// `FFLARNC: load-enable and asynchronous active-low reset and synchronous active-high clear
// `FFLSR:   load-enable and synchronous active-high reset
// `FFLSRN:  load-enable and synchronous active-low reset
// `FFLNR:   load-enable without reset






// Flip-Flop with asynchronous active-low reset
// __q: Q output of FF
// __d: D input of FF
// __reset_value: value assigned upon reset
// (__clk: clock input)
// (__arst_n: asynchronous reset, active-low)


// Flip-Flop with asynchronous active-high reset
// __q: Q output of FF
// __d: D input of FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst: asynchronous reset, active-high


// DEPRECATED - use `FF instead
// Flip-Flop with asynchronous active-low reset
// __q: Q output of FF
// __d: D input of FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst_n: asynchronous reset, active-low


// Flip-Flop with synchronous active-high reset
// __q: Q output of FF
// __d: D input of FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __reset_clk: reset input, active-high


// Flip-Flop with synchronous active-low reset
// __q: Q output of FF
// __d: D input of FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __reset_n_clk: reset input, active-low


// Always-enable Flip-Flop without reset
// __q: Q output of FF
// __d: D input of FF
// __clk: clock input


// Flip-Flop with load-enable and asynchronous active-low reset (implicit clock and reset)
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __reset_value: value assigned upon reset
// (__clk: clock input)
// (__arst_n: asynchronous reset, active-low)


// Flip-Flop with load-enable and asynchronous active-high reset
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst: asynchronous reset, active-high


// DEPRECATED - use `FFL instead
// Flip-Flop with load-enable and asynchronous active-low reset
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst_n: asynchronous reset, active-low


// Flip-Flop with load-enable and synchronous active-high reset
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __reset_clk: reset input, active-high


// Flip-Flop with load-enable and synchronous active-low reset
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __reset_n_clk: reset input, active-low


// Flip-Flop with load-enable and asynchronous active-low reset and synchronous clear
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __clear: assign reset value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst_n: asynchronous reset, active-low


// Flip-Flop with asynchronous active-low reset and synchronous clear
// __q: Q output of FF
// __d: D input of FF
// __clear: assign reset value into FF
// __reset_value: value assigned upon reset
// __clk: clock input
// __arst_n: asynchronous reset, active-low


// Load-enable Flip-Flop without reset
// __q: Q output of FF
// __d: D input of FF
// __load: load d value into FF
// __clk: clock input





  logic   [idx_width(idx_width(8*NrLanes)):0] popc_d, popc_q;
  logic [idx_width(idx_width(8*NrLanes))-1:0] next_stride_first_d, next_stride_first_q;
  logic            [idx_width(8*NrLanes)-1:0] next_spare_stride, next_stride;
  logic            [idx_width(8*NrLanes)-1:0] spare_stride_d, spare_stride_q;
  logic                                       ff_en, next_stride_zero_d, next_stride_zero_q;

  assign next_stride = valid_i ? stride_i : next_spare_stride;
  assign next_spare_stride = spare_stride_q ^ stride_p2_o;
  assign popc_o  = popc_q;
  assign ff_en   = valid_i | update_i;
  assign valid_o = ~next_stride_zero_q;
  assign spare_stride_d = next_stride;

    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin                                    
    if (!rst_ni) begin                                                                      
      popc_q <= ('0);                                                                 
    end else begin                                                                            
      if (ff_en) begin                                                                       
        popc_q <= (popc_d);                                                                         
      end                                                                                     
    end                                                                                       
  end;
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin                                    
    if (!rst_ni) begin                                                                      
      next_stride_first_q <= ('0);                                                                 
    end else begin                                                                            
      if (ff_en) begin                                                                       
        next_stride_first_q <= (next_stride_first_d);                                                                         
      end                                                                                     
    end                                                                                       
  end;
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin                                    
    if (!rst_ni) begin                                                                      
      next_stride_zero_q <= ('0);                                                                 
    end else begin                                                                            
      if (ff_en) begin                                                                       
        next_stride_zero_q <= (next_stride_zero_d);                                                                         
      end                                                                                     
    end                                                                                       
  end;
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin                                    
    if (!rst_ni) begin                                                                      
      spare_stride_q <= ('0);                                                                 
    end else begin                                                                            
      if (ff_en) begin                                                                       
        spare_stride_q <= (spare_stride_d);                                                                         
      end                                                                                     
    end                                                                                       
  end;

  // Is the stride power of two?
  popcount #(
    .INPUT_WIDTH (idx_width(8*NrLanes))
  ) i_sldu_stride_popc (
    .data_i     (next_stride),
    .popcount_o (popc_d     )
  );

  // Where is the first one in the stride?
  lzc #(
    .WIDTH (idx_width(8*NrLanes)),
    .MODE  (0                   )
  ) i_sldu_stride_clz (
    .in_i    (next_stride        ),
    .cnt_o   (next_stride_first_d),
    .empty_o (next_stride_zero_d )
  );

  always_comb begin
    stride_p2_o = '0;
    for (int b = 0; b < idx_width(8*NrLanes); b++)
      if (b == next_stride_first_q)
        stride_p2_o[b] = ~next_stride_zero_q;
  end

endmodule
