// Accelerator - CVA6's












/////////////////////////
// Exception data type //
/////////////////////////




  // Vector configuration
  localparam int unsigned NrLanes = 2;
  localparam int unsigned VLEN    = 4096;

  localparam int unsigned OSSupport    = 1;
  localparam fpu_support_e   FPUSupport   = FPUSupportHalfSingleDouble;
  localparam fpext_support_e FPExtSupport = FPExtSupportEnable;
  localparam fixpt_support_e FixPtSupport = FixedPointEnable;
  localparam seg_support_e   SegSupport   = SegSupportEnable;

  // AXI configuration (matches ara_soc defaults for NrLanes=2)
  localparam int unsigned AxiDataWidth       = 32 * NrLanes;
  localparam int unsigned AxiAddrWidth       = 64;
  localparam int unsigned AxiUserWidth       = 1;
  localparam int unsigned AxiIdWidth         = 5;
  localparam int unsigned AxiNarrowDataWidth = 64;

  // NrAXIMasters = 1 -> AxiSocIdWidth = AxiIdWidth - clog2(1) = AxiIdWidth
  localparam int unsigned AxiSocIdWidth  = AxiIdWidth;
  localparam int unsigned AxiCoreIdWidth = AxiSocIdWidth - 1;

  // Memory map (consumed by the CVA6 config generator below)
  localparam logic [63:0] DRAMBase   = 64'h8000_0000;
  localparam logic [63:0] UARTBase   = 64'hC000_0000;
  localparam logic [63:0] CTRLBase   = 64'hD000_0000;
  localparam logic [63:0] DRAMLength = 64'h4000_0000;
  localparam logic [63:0] UARTLength = 64'h1000;
  localparam logic [63:0] CTRLLength = 64'h1000;

  // AXI struct types for Ara's wide memory port
  typedef logic [AxiDataWidth-1:0]   axi_data_t;
  typedef logic [AxiDataWidth/8-1:0] axi_strb_t;
  typedef logic [AxiAddrWidth-1:0]   axi_addr_t;
  typedef logic [AxiUserWidth-1:0]   axi_user_t;
  typedef logic [AxiCoreIdWidth-1:0] axi_core_id_t;

        typedef struct packed {                                       
    axi_core_id_t              id;                                       
    axi_addr_t            addr;                                     
    axi_pkg::len_t    len;                                      
    axi_pkg::size_t   size;                                     
    axi_pkg::burst_t  burst;                                    
    logic             lock;                                     
    axi_pkg::cache_t  cache;                                    
    axi_pkg::prot_t   prot;                                     
    axi_pkg::qos_t    qos;                                      
    axi_pkg::region_t region;                                   
    axi_pkg::atop_t   atop;                                     
    axi_user_t            user;                                     
  } ara_axi_aw_chan_t;                         
    typedef struct packed {                                       
    axi_data_t data;                                                
    axi_strb_t strb;                                                
    logic  last;                                                
    axi_user_t user;                                                
  } ara_axi_w_chan_t;                         
    typedef struct packed {                             
    axi_core_id_t            id;                               
    axi_pkg::resp_t resp;                             
    axi_user_t          user;                             
  } ara_axi_b_chan_t;                                     
    typedef struct packed {                                       
    axi_core_id_t              id;                                       
    axi_addr_t            addr;                                     
    axi_pkg::len_t    len;                                      
    axi_pkg::size_t   size;                                     
    axi_pkg::burst_t  burst;                                    
    logic             lock;                                     
    axi_pkg::cache_t  cache;                                    
    axi_pkg::prot_t   prot;                                     
    axi_pkg::qos_t    qos;                                      
    axi_pkg::region_t region;                                   
    axi_user_t            user;                                     
  } ara_axi_ar_chan_t;                         
    typedef struct packed {                                     
    axi_core_id_t            id;                                       
    axi_data_t          data;                                     
    axi_pkg::resp_t resp;                                     
    logic           last;                                     
    axi_user_t          user;                                     
  } ara_axi_r_chan_t;                           
    typedef struct packed {                                         
    ara_axi_aw_chan_t aw;                                                 
    logic     aw_valid;                                           
    ara_axi_w_chan_t  w;                                                  
    logic     w_valid;                                            
    logic     b_ready;                                            
    ara_axi_ar_chan_t ar;                                                 
    logic     ar_valid;                                           
    logic     r_ready;                                            
  } ara_axi_req_t;           
    typedef struct packed {                               
    logic     aw_ready;                                 
    logic     ar_ready;                                 
    logic     w_ready;                                  
    logic     b_valid;                                  
    ara_axi_b_chan_t  b;                                        
    logic     r_valid;                                  
    ara_axi_r_chan_t  r;                                        
  } ara_axi_resp_t;

  // Derive a CVA6 config for Ara from the template config (see ara_soc.sv)
  function automatic config_pkg::cva6_user_cfg_t gen_usr_cva6_config(config_pkg::cva6_user_cfg_t cfg);
    cfg.AxiAddrWidth          = AxiAddrWidth;
    cfg.AxiDataWidth          = AxiNarrowDataWidth;
    cfg.AxiIdWidth            = AxiIdWidth;
    cfg.AxiUserWidth          = AxiUserWidth;
    cfg.XF16                  = FPUSupport[3];
    cfg.RVF                   = FPUSupport[4];
    cfg.RVD                   = FPUSupport[5];
    cfg.XF16ALT               = FPUSupport[2];
    cfg.XF8                   = FPUSupport[1];
    cfg.NrPMPEntries          = 0;
    cfg.NrNonIdempotentRules  = 2;
    cfg.NonIdempotentAddrBase = {UARTBase, CTRLBase};
    cfg.NonIdempotentLength   = {UARTLength, CTRLLength};
    cfg.NrExecuteRegionRules  = 3;
    cfg.ExecuteRegionAddrBase = {DRAMBase, 64'h1_0000, 64'h0};
    cfg.ExecuteRegionLength   = {DRAMLength, 64'h10000, 64'h1000};
    cfg.NrCachedRegionRules   = 1;
    cfg.CachedRegionAddrBase  = {DRAMBase};
    cfg.CachedRegionLength    = {DRAMLength};
    return cfg;
  endfunction

  localparam config_pkg::cva6_user_cfg_t CVA6AraConfig_user =
      gen_usr_cva6_config(cva6_config_pkg::cva6_cfg);
  localparam config_pkg::cva6_cfg_t CVA6AraConfig =
      build_config_pkg::build_config(CVA6AraConfig_user);

  // CVA6 accelerator interface types
    typedef struct packed {                                      
    
    logic [CVA6AraConfig.XLEN-1:0] cause;                            
    
    
    logic [CVA6AraConfig.XLEN-1:0] tval;                             
    
    
    logic [CVA6AraConfig.GPLEN-1:0] tval2;                           
    
    logic [31:0] tinst;                                        
    
    logic gva  ;                                               
    logic valid;                                               
  } exception_t;;
    typedef struct packed {                                                  
    logic                             req_valid;                           
    logic                             resp_ready;                          
    logic [31:0]                      insn;                                
    logic [CVA6AraConfig.XLEN-1:0]          rs1;                                 
    logic [CVA6AraConfig.XLEN-1:0]          rs2;                                 
    fpnew_pkg::roundmode_e                       frm;                                 
    logic [CVA6AraConfig.TRANS_ID_BITS-1:0] trans_id;                            
    logic                             store_pending;                       
    logic                             acc_cons_en;                         
    logic                             inval_ready;                         
  } accelerator_req_t;;
    typedef struct packed {                                                    
    logic                              req_ready;                            
    logic                              resp_valid;                           
    logic [CVA6AraConfig.XLEN-1:0]           result;                               
    logic [CVA6AraConfig.TRANS_ID_BITS-1:0]  trans_id;                             
    exception_t                        exception;                            
    logic                              store_pending;                        
    logic                              store_complete;                       
    logic                              load_complete;                        
    logic [4:0]                        fflags;                               
    logic                              fflags_valid;                         
    logic                              inval_valid;                          
    logic [63:0]                       inval_addr;                           
  } accelerator_resp_t;;
    typedef struct packed {                                 
    logic                    acc_mmu_misaligned_ex;       
    logic                    acc_mmu_req;                 
    logic [CVA6AraConfig.VLEN-1:0] acc_mmu_vaddr;               
    logic                    acc_mmu_is_store;            
  } acc_mmu_req_t;;
    typedef struct packed {                                                
    logic                    acc_mmu_dtlb_hit;                           
    logic [CVA6AraConfig.PPNW-1:0] acc_mmu_dtlb_ppn;                           
    logic                    acc_mmu_valid;                              
    logic [CVA6AraConfig.PLEN-1:0] acc_mmu_paddr;                              
    exception_t              acc_mmu_exception;                          
  } acc_mmu_resp_t;;
    typedef struct packed {                                                               
    accelerator_req_t acc_req;                                                          
    logic             acc_mmu_en;                                                       
    acc_mmu_resp_t    acc_mmu_resp;                                                     
  } cva6_to_acc_t;;
    typedef struct packed {                                                               
    accelerator_resp_t acc_resp;                                                        
    acc_mmu_req_t      acc_mmu_req;                                                     
  } acc_to_cva6_t;;

endpackage

module ara_wrap
  import ara_wrap_pkg::*;
  (
   input  logic          clk_i,
   input  logic          rst_ni,
   input  logic          scan_enable_i,
   input  logic          scan_data_i,
   output logic          scan_data_o,
   // Interface with the scalar core
   input  cva6_to_acc_t  acc_req_i,
   output acc_to_cva6_t  acc_resp_o,
   // AXI memory interface
   output ara_axi_req_t  axi_req_o,
   input  ara_axi_resp_t axi_resp_i
   );

   ara #(
     .NrLanes           (NrLanes           ),
     .VLEN              (VLEN              ),
     .OSSupport         (OSSupport         ),
     .FPUSupport        (FPUSupport        ),
     .FPExtSupport      (FPExtSupport      ),
     .FixPtSupport      (FixPtSupport      ),
     .SegSupport        (SegSupport        ),
     .CVA6Cfg           (CVA6AraConfig     ),
     .exception_t       (exception_t       ),
     .accelerator_req_t (accelerator_req_t ),
     .accelerator_resp_t(accelerator_resp_t),
     .acc_mmu_req_t     (acc_mmu_req_t     ),
     .acc_mmu_resp_t    (acc_mmu_resp_t    ),
     .cva6_to_acc_t     (cva6_to_acc_t     ),
     .acc_to_cva6_t     (acc_to_cva6_t     ),
     .AxiDataWidth      (AxiDataWidth      ),
     .AxiAddrWidth      (AxiAddrWidth      ),
     .axi_ar_t          (ara_axi_ar_chan_t ),
     .axi_r_t           (ara_axi_r_chan_t  ),
     .axi_aw_t          (ara_axi_aw_chan_t ),
     .axi_w_t           (ara_axi_w_chan_t  ),
     .axi_b_t           (ara_axi_b_chan_t  ),
     .axi_req_t         (ara_axi_req_t     ),
     .axi_resp_t        (ara_axi_resp_t    )
   ) i_ara (
     .clk_i        (clk_i        ),
     .rst_ni       (rst_ni       ),
     .scan_enable_i(scan_enable_i),
     .scan_data_i  (scan_data_i  ),
     .scan_data_o  (scan_data_o  ),
     .acc_req_i    (acc_req_i    ),
     .acc_resp_o   (acc_resp_o   ),
     .axi_req_o    (axi_req_o    ),
     .axi_resp_i   (axi_resp_i   )
   );

endmodule
